using System;using System.Data;using System.Data.SqlClient;using System.Drawing;using System.Windows.Forms;using AshkanJobCenter.Core;using AshkanJobCenter.Data;
namespace AshkanJobCenter.UI{public class KanbanPage:UserControl{readonly string[] stages={"Applied","Screening","Interview","Offer","Hired","Rejected"};FlowLayoutPanel board;public KanbanPage(){BackColor=Theme.Background;Padding=new Padding(8);var top=new Panel{Dock=DockStyle.Top,Height=50};var title=Ui.Label(L.Fa?"برد فرآیند استخدام":"Recruitment Kanban",18,true);title.Dock=DockStyle.Left;var refresh=Ui.Button(L.Fa?"بروزرسانی":"Refresh",false);refresh.Dock=DockStyle.Right;refresh.Click+=(s,e)=>LoadBoard();top.Controls.Add(title);top.Controls.Add(refresh);Controls.Add(top);board=new FlowLayoutPanel{Dock=DockStyle.Fill,AutoScroll=true,WrapContents=false,FlowDirection=FlowDirection.LeftToRight};Controls.Add(board);board.BringToFront();LoadBoard();}void LoadBoard(){board.Controls.Clear();foreach(string stage in stages){var col=new FlowLayoutPanel{Width=245,Height=Math.Max(500,Height-80),AutoScroll=true,WrapContents=false,FlowDirection=FlowDirection.TopDown,BackColor=Color.White,Padding=new Padding(8)};var h=Ui.Label(stage,12,true);h.Width=215;h.Height=35;col.Controls.Add(h);var t=Database.Query("SELECT a.Id,c.FullName,j.Title,a.Score FROM Applications a JOIN Candidates c ON c.Id=a.CandidateId JOIN Jobs j ON j.Id=a.JobId WHERE a.Stage=@s ORDER BY a.Id DESC",new SqlParameter("@s",stage));foreach(DataRow r in t.Rows){var card=Ui.Card();card.Width=210;card.Height=115;var l=Ui.Label(Convert.ToString(r["FullName"])+"\n"+Convert.ToString(r["Title"])+"\nScore: "+Convert.ToString(r["Score"]),9,true);l.Dock=DockStyle.Top;l.Height=72;card.Controls.Add(l);if(AppSession.Can("Applications.Manage")){var next=Ui.Button(L.Fa?"مرحله بعد":"Next",false);next.Dock=DockStyle.Bottom;int id=Convert.ToInt32(r["Id"]);string st=stage;next.Click+=(s,e)=>MoveNext(id,st);card.Controls.Add(next);}col.Controls.Add(card);}board.Controls.Add(col);}}void MoveNext(int id,string stage){int i=Array.IndexOf(stages,stage);if(i<0||i>=stages.Length-2)return;string n=stages[i+1];Database.Exec("UPDATE Applications SET Stage=@s WHERE Id=@id",new SqlParameter("@s",n),new SqlParameter("@id",id));Database.Audit("KanbanMove","Application",id+" "+stage+" -> "+n);LoadBoard();}}
}
